WITH flattened_attrs AS (SELECT id, customer_id, created_at, items, attributes, ARRAY_CONTAINS(MAP_KEYS(attributes), 'utm_source') AS has_utm_source, COALESCE(attributes['device'], 'unknown') AS device_or_default FROM carts) SELECT DATE_TRUNC('DAY', created_at) AS activity_day, COUNT(*) AS num_rows, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS span_minutes, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS duration_min FROM flattened_attrs GROUP BY activity_day ORDER BY num_rows DESC NULLS LAST;
